namespace Berwick.Core;

/// <summary>What a skill does, in plain words. Kind is "Command" for skills chosen from the command menu, otherwise how it works.
/// Source says how each part is known: checked in a running game, read from the game program, or taken from the game's own description.</summary>
public sealed record SkillInfo(string Name, string Kind, string Summary, string Details, string Source);

public static class SkillCatalog
